for r in rows[:5]: print(r['set_id'],r['model'],r['mean'])
# pair exact A/B
d=defaultdict(list)
for r in rows:d[r['set_id']].append(r)
wins=ties=0; pairs=[]
for sid,rs in d.items():
 a=[r for r in rs if r['activation']=='gelu' and not r['residual'] and r['layer_norm']==[False]]
 b=[r for r in rs if r['activation']=='leaky_relu' and r['residual'] and r['layer_norm']==[True]]
 if a and b:
  wins += b[0]['mean']<a[0]['mean']; ties += b[0]['mean']==a[0]['mean']; pairs.append((b[0]['mean']-a[0]['mean'],sid))
print('pairs',len(pairs),'B wins',wins,'ties',ties,'deltas',pairs[:10])
